// C11 版本
#include <stdatomic.h>
typedef struct { _Atomic int locked; } SpinLock;

void spin_init(SpinLock* lk) { atomic_store(&lk->locked, 0); }

void spin_lock(SpinLock* lk) {
  // CAS：期望 0（空闲），成功则置 1；失败就忙等重试
  int expected = 0;
  while (!atomic_compare_exchange_weak(&lk->locked, &expected, 1)) {
    expected = 0;  // 失败后 expected 会被写成当前值，需重置
    // 可加 PAUSE/YIELD 指令降低功耗与缓存压力
  }
}

void spin_unlock(SpinLock* lk) {
  atomic_store(&lk->locked, 0);  // 持有者独占写，无需 CAS
}

