semaphore empty = N;   // 空槽位数
semaphore full  = 0;   // 已生产产品数
semaphore mutex = 1;   // 缓冲区互斥
buffer_t buf[N];

producer() {
  while (true) {
    item x = produce();
    P(empty);          // 1. 先申请资源：没槽位就阻塞，但不持锁
    P(mutex);          // 2. 再申请互斥进入临界区
    buf[in] = x; in = (in + 1) % N;
    V(mutex);          // 3. 出临界区，尽早放锁
    V(full);           // 4. 通知消费者有货
  }
}

consumer() {
  while (true) {
    P(full);           // 1. 没产品就阻塞，不持锁
    P(mutex);          // 2. 进临界区
    item x = buf[out]; out = (out + 1) % N;
    V(mutex);          // 3. 放锁
    V(empty);          // 4. 归还槽位、唤醒生产者
    consume(x);
  }
}
